const items=[{name:'The Butter Croissant',description:'Golden, flaky layers with a very buttery center.',price:'$5',type:'pastry',tag:'THE CLASSIC'},{name:'Raspberry Swirl',description:'A bright berry ribbon wrapped in soft, tender dough.',price:'$6',type:'pastry',tag:'A LITTLE TART'},{name:'Morning Bun',description:'A cinnamon-sugar hug with crisp, caramelized edges.',price:'$5',type:'pastry',tag:'CROWD FAVORITE'},{name:'Everyday Sourdough',description:'A crackly crust, a soft middle, and plenty of character.',price:'$9',type:'bread',tag:'THE DAILY LOAF'},{name:'Olive & Herb Focaccia',description:'Pillowy, golden, and generously dotted with herbs.',price:'$8',type:'bread',tag:'SAVORY SIDE'},{name:'Honey Oat Loaf',description:'A soft, wholesome slice made for a little extra butter.',price:'$9',type:'bread',tag:'TOAST ME'}];const grid=document.querySelector('#menu-grid');function render(filter){grid.innerHTML=items.filter(item=>filter==='all'||item.type===filter).map(item=>`<article class="menu-item"><div class="item-top"><h3>${item.name}</h3><span>${item.price}</span></div><p>${item.description}</p><span class="item-tag">${item.tag}</span></article>`).join('')}document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});render(button.dataset.filter)}));render('all');
